const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.notifiedExecutionIds)) {
  staticData.notifiedExecutionIds = [];
}

const executionId = String((data.execution && data.execution.id) || '');
const alreadyNotified = Boolean(executionId) && staticData.notifiedExecutionIds.includes(executionId);

if (!alreadyNotified && executionId) {
  staticData.notifiedExecutionIds.push(executionId);
  // Keep static data well under the 64KB cap by only remembering the most recent 200 execution IDs.
  if (staticData.notifiedExecutionIds.length > 200) {
    staticData.notifiedExecutionIds = staticData.notifiedExecutionIds.slice(-200);
  }
}

const workflowName = (data.workflow && data.workflow.name) || 'Unknown workflow';
const errorMessage = (data.execution && data.execution.error && data.execution.error.message) || 'No error message provided';
const lastNode = (data.execution && data.execution.lastNodeExecuted) || 'Unknown node';
const mode = (data.execution && data.execution.mode) || 'unknown';
const executionUrl = (data.execution && data.execution.url) || '';

return [{
  json: { alreadyNotified, executionId, workflowName, errorMessage, lastNode, mode, executionUrl }
}];

const config = $input.first().json;
const err = $('Check duplicate & summarize error').first().json;

const lines = [
  `:rotating_light: *${err.workflowName}* failed`,
  `*Node:* ${err.lastNode}`,
  `*Error:* ${err.errorMessage}`
];
if (err.executionUrl) lines.push(`*Execution:* ${err.executionUrl}`);
lines.push(`*Mode:* ${err.mode}`);

return [{ json: { slackWebhookUrl: config.slackWebhookUrl, slackRequestBody: { text: lines.join('\n') } } }];

